// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));

        uint256 sendAmt = bound(amount, 0, 100 ether);
        vm.deal(actor, sendAmt);

        uint256 before = c.pastBlockTime();

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: sendAmt}("");

        if (sendAmt != 10 ether) {
            assertTrue(c.pastBlockTime() == before);
        } else {
            assertTrue(c.pastBlockTime() >= before);
        }
    }
}
